import { GameControls } from "../Controls/GameControls";
import { BaseComponent } from "../../../utils/baseElement";
import { GameBoard } from "../../GameBoard/GameBoard";
import styles from "./Main.module.scss";
import { stateMachine } from "../../../core/StateMachine";
import { ControlsController } from "../Controls/ControlsController";
import { TemplateSelector } from "../Controls/TemplateSelector";
import { levelConfig } from "../../../core/levelConfig";
import { TemplateController } from "../Controls/TemplateController";

class Main extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   */
  constructor() {
    super({ tag: "main", className: styles.main });
    this.controlsManager = new ControlsController(stateMachine);
    this.templateManager = new TemplateController(levelConfig);
    this.getNode();
    this.addInvitation();
    this.addTemplateSelector();
    this.addControls();
    this.addGameBoard();
  }
  addInvitation() {
    const h2 = new BaseComponent({
      tag: "h2",
      className: styles.invitation,
      text: "Hi! Do you wanna choose a game? ",
    });
    this.append(h2);
  }

  addTemplateSelector() {
    const templateSelector = new TemplateSelector(
      levelConfig,
      this.templateManager,
    );
    this.append(templateSelector);
  }

  addControls() {
    const controls = new GameControls(this.controlsManager);
    this.append(controls);
  }

  addGameBoard() {
    const gameBoard = new GameBoard(this.templateManager);
    this.append(gameBoard);
  }
}

export { Main }; //wrapper
