import { BaseComponent } from "../../utils/baseElement";
import { Cell } from "../Cell/Cell";
import styles from "./GameBoard.module.scss";

class GameBoard extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   * @param {number} width
   * @param {number} height
   */
  constructor(templateManager) {
    super({ tag: "section", className: styles.gameBoard });
    this.templateManager = templateManager;
    this.updateGameBoard();
    this.templateManager.onTemplateChange(() => this.updateGameBoard());
  }

  addCells() {
    const cells = Array.from({ length: this.calculateNumberOfCells() }).map(
      () => {
        const cell = new Cell();
        this.append(cell);
        return cell.getNode();
      },
    );
    this.append(...cells);
  }

  calculateNumberOfCells() {
    return this.width ** 2;
  }

  updateGameBoard() {
    this.destroyChildren();
    this.getNode().classList.remove(styles.easy, styles.medium, styles.hard);

    const template = this.templateManager.getSelectedTemplate();
    if (template) {
      this.width = template.size;
      this.getNode().classList.add(styles[template.difficulty]);
      this.addCells();
      // TODO добавить обновление подсказок
    } else {
      this.destroyChildren();
      this.width = 5;
      this.getNode().classList.add(styles.easy);
      this.addCells();
    }
  }
}

export { GameBoard }; // main
